fn test_numbering_patterns() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("1.2.3 Title")[..]), 1, "1.2.3: decimal");
    crate::testport::assert_eq(crate::port::cells_at(ws, 1), 3, "of depth three");
    crate::testport::assert_eq(crate::port::cells_at(ws, 2), 0, "the number starts the line");
    crate::testport::assert_eq(crate::port::cells_at(ws, 3), 5, "and is five code points");
    crate::testport::assert_eq(crate::port::cells_at(ws, 4), 6, "the title is six further on");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("2. Methods")[..]), 1, "2.: decimal");
    crate::testport::assert_eq(crate::port::cells_at(ws, 1), 1, "of depth one");
    crate::testport::assert_eq(crate::port::cells_at(ws, 3), 1, "the dot is not part of the number");
    crate::testport::assert_eq(crate::port::cells_at(ws, 4), 3, "but it is skipped");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("IV. Rules")[..]), 2, "IV.: upper roman");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("A. Name")[..]), 4, "A.: upper letter");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, (&crate::testport::text_blob("b) item")[..])), 5, "b): lower letter");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("(iv) item")[..]), 3, "(iv): lower roman");
    crate::testport::assert_eq(crate::port::cells_at(ws, 2), 1, "its number starts after the bracket");
    crate::testport::assert_eq(crate::port::cells_at(ws, 3), 2, "and is two code points");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("§ 4.1 Scope")[..]), 7, "a section sign and a number");
    crate::testport::assert_eq(crate::port::cells_at(ws, 1), 2, "depth two");
    crate::testport::assert_eq(crate::port::cells_at(ws, 2), 2, "the number is after the sign");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("Chapter 3 Formation")[..]), 6, "a capitalised word and a number: a keyword form, no table needed");
    crate::testport::assert_eq(crate::port::cells_at(ws, 3), 9, "`Chapter 3` is the number");
    crate::testport::assert_eq(crate::port::cells_at(ws, 4), 10, "the title follows");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("Article 1.1 Name")[..]), 6, "Article 1.1");
    crate::testport::assert_eq(crate::port::cells_at(ws, 1), 2, "dotted depth counts for a keyword form too");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("Kapitel IV Anfang")[..]), 6, "another language, the same pattern");
    crate::testport::assert_eq(ht_marker(wd, ln, et, ws, &crate::testport::text_blob("Appendix A: Data")[..]), 6, "a capital letter and a colon");
    crate::testport::assert_eq(crate::port::cells_at(ws, 3), 10, "`Appendix A`");
}
