    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ptxt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ht_outline_doc(wd, ln, et);
    crate::testport::assert_eq(ht_run(wd, ln, et, sf, sc, hc, ws, tmp, pr, ptxt), 5, "five headings");
    crate::testport::assert_eq(hd_level(hc, 0), 1, "the title in 9.5 pt capitals is level 1: it comes first and nothing is above it");
    crate::testport::assert_eq(hd_level(hc, 4), 2, "the 21 pt section under it is level 2, though it prints bigger");
    crate::testport::assert_eq(hd_level(hc, 7), 3, "the 11.5 pt subsection is level 3");
    crate::testport::assert_eq(hd_level(hc, 10), 2, "the next 21 pt section is level 2 again");
    crate::testport::assert_eq(hd_level(hc, 13), 1, "the next small title is level 1 again");
